def calculate_safety_factor(max_interface_stress, stress):
    """
    Calculate the safety factor.
    Args:
    max_interface_stress (float): Maximum withstandable stress of the interface in MPa.
    stress (float): Current stress in MPa.
    Returns:
    float: Safety factor, returns infinity if stress is zero.
    """
    if stress > 0:
        return max_interface_stress / stress
    else:
        return float('inf')
